Object.assign(I18N.th,{nearMe:'ใกล้ฉัน',nearActive:'สถานที่ใกล้ฉัน',locating:'กำลังค้นหาตำแหน่ง…',stopNear:'ดูทั้งหมด',radius:'ระยะทาง',budget:'งบประมาณ',anyBudget:'ทุกราคา',noLocal:'ยังไม่มีสถานที่จริงที่เผยแพร่ใกล้ตำแหน่งนี้',locationDenied:'ไม่สามารถรับตำแหน่งได้ โปรดอนุญาต GPS ในเบราว์เซอร์',localOnly:'ค้นหาใกล้ฉันรองรับสถานที่ที่เผยแพร่แล้วเท่านั้น',distKm:'กม. จากคุณ',startingFrom:'เริ่มต้น',modeDrive:'รถยนต์',modeWalk:'เดิน',modeTransit:'ขนส่งสาธารณะ',verifyEmail:'ยืนยันอีเมล',emailUnverified:'ยังไม่ได้ยืนยันอีเมล',emailVerified:'ยืนยันอีเมลแล้ว',sendVerify:'ส่งลิงก์ยืนยันอีเมล',forgotPassword:'ลืมรหัสผ่าน?',resetPassword:'ตั้งรหัสผ่านใหม่',sendReset:'ส่งลิงก์ตั้งรหัสผ่าน',backToLogin:'กลับไปเข้าสู่ระบบ',emailCheck:'ตรวจอีเมล หรือดูหน้าต่างเซิร์ฟเวอร์ในโหมดทดลอง',resetReady:'เปลี่ยนรหัสผ่านสำเร็จ กรุณาเข้าสู่ระบบใหม่',changeName:'แก้ชื่อที่แสดง',saveName:'บันทึกชื่อ',profileUpdated:'อัปเดตโปรไฟล์แล้ว',sendLink:'ส่งลิงก์'});
I18N.en.filters='Filters';I18N.th.filters='ตัวกรอง';
const t=k=>I18N[state.lang][k]||k;
const name=p=>state.lang==='th'?(p.th||p.en):p.en;
const loc=p=>state.lang==='th'?(p.locTh||p.locEn):p.locEn;
const story=p=>state.lang==='th'?(p.storyTh||p.storyEn):p.storyEn;
const photo=p=>typeof p==='string' && p.startsWith('/uploads/')?p:`assets/${p||'hero-forest.webp'}`;
function store(){try{localStorage.setItem(KEY,JSON.stringify({lang:state.lang,saved:state.account?guestSaved:state.saved,trip:state.account?guestTrip:state.trip,notes:state.notes,suggestions:state.suggestions}))}catch{}}
async function userApi(route,method='GET',data){const res=await fetch(route,{method,credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let json={};try{json=await res.json()}catch{}if(!res.ok)throw new Error(json.error||'Request failed');return json;}
async function loadAccountCollections(){if(!state.account)return;const [collections,reviews]=await Promise.all([userApi('/api/me/collections'),userApi('/api/me/reviews')]);state.saved=collections.saved;state.trip=collections.trip;state.myReviews=reviews.reviews;render({keepScroll:true});}
async function refreshSession(){try{const result=await userApi('/api/auth/me');if(result.user){state.account=result.user;await loadAccountCollections()}else if(state.account){state.account=null;state.saved=[...guestSaved];state.trip=[...guestTrip];state.myReviews=[];render({keepScroll:true})}}catch(err){console.info('Account service unavailable:',err.message)}}
let persistOrder=Promise.resolve();
function persistCollections(){if(!state.account||!LIVE_DATA){store();return}const payload={saved:[...state.saved],trip:[...state.trip]};persistOrder=persistOrder.catch(()=>{}).then(async()=>{try{await userApi('/api/me/collections','PUT',payload)}catch(e){toast(e.message);try{await loadAccountCollections()}catch{}}});}
async function loadReviewPage(id){if(!LIVE_DATA)return;try{const r=await userApi('/api/places/'+encodeURIComponent(id)+'/reviews');state.reviewCache[id]=r.reviews;if(state.page==='detail'&&state.detail===id)render({keepScroll:true})}catch(e){console.info('Review load:',e.message)}}
async function signOut(){try{await userApi('/api/auth/logout','POST');state.account=null;state.saved=[...guestSaved];state.trip=[...guestTrip];state.myReviews=[];state.reviewPhoto='';store();render({keepScroll:true})}catch(e){toast(e.message)}}
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('on'),2200)}
function actionBtn(action,content,extra='',attributes=''){return `<button type="button" class="${extra}" data-action="${action}" ${attributes}>${content}</button>`}
function brand(){return `<button class="brand" data-action="navigate" data-page="welcome" aria-label="unfold - ${html(t('homeLink'))}"><span class="brand-mark">u<span class="brand-dot">.</span></span><span class="brand-full">unfold</span></button>`}
function header(){return `<header class="site-header">${brand()}<nav class="header-links" aria-label="Primary">${[['discover','discover'],['map','map'],['saved','saved'],['trip','trip']].map(([page,label])=>`<button data-action="navigate" data-page="${page}" class="${state.page===page?'selected':''}">${html(t(label))}</button>`).join('')}</nav><div class="head-actions"><button class="language-btn" data-action="language" aria-label="Change language">${state.lang==='en'?'TH':'EN'}</button>${actionBtn('search-open',ico('search',20),'header-icon','aria-label="Search"')}${actionBtn('menu-open',ico('menu',23),'header-icon menu-trigger','aria-label="Open menu"')}</div></header>`}
function bottomNav(){return `<nav class="bottom-nav" aria-label="App navigation">${[['discover','home'],['map','compass'],['saved','heart'],['profile','user']].map(([page,glyph])=>`<button data-action="navigate" data-page="${page}" class="${state.page===page||(page==='saved'&&state.page==='trip')?'selected':''}" aria-label="${html(t(page))}" ${state.page===page?'aria-current="page"':''}>${ico(glyph,23)}<span class="nav-tooltip">${html(t(page))}</span></button>`).join('')}</nav>`}
function landing(){return `<div class="landing" id="landing"><div class="landing-image"><img src="${photo('hero-forest.webp')}" alt="Scenic mountain lake and forest"/></div><div class="landing-shade"></div><div class="landing-header">${brand()}<div class="landing-header-right"><button class="landing-language" data-action="language">${state.lang==='en'?'TH':'EN'}</button>${actionBtn('menu-open',ico('menu',23),'landing-menu','aria-label="Menu"')}</div></div><div class="landing-copy"><p class="mini-overline">${html(t('homeEyebrow'))}</p><h1>${html(t('homeTitle')).replace('\n','<br>')}</h1><p class="landing-subline">${html(t('homeDesc'))}</p><button data-action="navigate" data-page="discover" class="landing-cta"><span>${html(t('homeExplore'))}</span>${ico('arrow',20)}</button></div><div class="landing-bottom"><span>01 / 03</span><div class="landing-line"><i></i></div><span>${html(t('homeHint'))}</span></div><button class="mobile-landing-go" data-action="navigate" data-page="discover">${html(t('enter'))}${ico('arrow',23)}</button><div class="landing-floating"><img src="${photo('ridge-view.webp')}" alt="Scenic valley"/><div><b>THE UNEXPECTED</b><span>${html(t('homeHint'))}</span></div><button data-action="navigate" data-page="discover" aria-label="Explore destinations">${ico('arrow',18)}</button></div></div>`}
function categoryButtons(){return `<div class="category-list" role="group" aria-label="Category">${CATEGORIES.map(cat=>`<button class="category-pill ${state.category===cat?'active':''}" data-action="category" data-category="${cat}" aria-pressed="${state.category===cat}">${ico(({all:'spark',nature:'tree',food:'coffee',stay:'bed',culture:'camera'})[cat],16)}<span>${html(t(cat))}</span></button>`).join('')}</div>`}
function filteredPlaces(){const q=state.query.trim().toLowerCase();return (state.nearbyActive?state.nearbyList:PLACES).filter(p=>(state.category==='all'||p.category===state.category)&&(state.region==='all'||p.region===state.region)&&(state.nearbyMaxPrice===''||!LIVE_DATA||state.nearbyActive||(p.priceFrom!=null&&p.currency===state.nearbyCurrency&&p.priceFrom<=Number(state.nearbyMaxPrice)))&&(!q||[p.en,p.th,p.locEn,p.locTh,p.storyEn,p.storyTh].join(' ').toLowerCase().includes(q)))}
function heartButton(p,moreClass=''){return `<button data-action="save" data-id="${p.id}" class="heart-button ${moreClass} ${state.saved.includes(p.id)?'on':''}" aria-label="${html(state.saved.includes(p.id)?t('unsave'):t('save'))} ${html(name(p))}" aria-pressed="${state.saved.includes(p.id)}">${ico('heart',21)}</button>`}
function placeCard(p,compact=false){return `<article class="place-card ${compact?'compact':''}" data-place="${p.id}"><div class="place-picture"><img src="${photo(p.photo)}" alt="Travel design preview illustration" loading="lazy"/><span class="card-gradient"></span><button class="place-card-link" data-action="place" data-id="${p.id}" aria-label="${html(t('view'))}: ${html(name(p))}"></button>${heartButton(p)}<span class="card-caption"><b>${html(name(p))}</b><small>${html(loc(p))}${p.distanceKm!=null?` · ${html(String(p.distanceKm))} ${html(t('distKm'))}`:''}</small></span></div></article>`}
function miniCard(p){return `<button class="mini-discovery" data-action="place" data-id="${p.id}"><img src="${photo(p.photo)}" alt="" loading="lazy"/><span><b>${html(name(p))}</b><small>${html(loc(p))}</small></span>${ico('arrow',17)}</button>`}

function nearbyControls(){return `<div class="nearby-tools"><button type="button" class="nearby-toggle ${state.nearbyActive?'on':''}" data-action="${state.nearbyActive?'nearby-stop':'nearby-start'}" ${state.nearbyBusy?'disabled':''}>${ico('pin',17)} ${html(t(state.nearbyBusy?'locating':state.nearbyActive?'stopNear':'nearMe'))}</button><button class="nearby-filter-toggle ${state.filtersOpen?'active':''}" type="button" data-action="filter-toggle" aria-expanded="${state.filtersOpen}">${ico('sliders',15)} ${html(t('filters'))}</button><div class="nearby-filter-fields ${state.filtersOpen?'expanded':''}"><label>${html(t('radius'))}<select id="near-radius" aria-label="${html(t('radius'))}">${[5,25,100,300].map(n=>`<option value="${n}" ${state.nearbyRadius===n?'selected':''}>${n} km</option>`).join('')}</select></label><label>${html(t('budget'))}<select id="near-price" aria-label="${html(t('budget'))}"><option value="">${html(t('anyBudget'))}</option>${[300,1000,3000,10000].map(n=>`<option value="${n}" ${state.nearbyMaxPrice===String(n)?'selected':''}>≤ ${n.toLocaleString()}</option>`).join('')}</select></label><label class="near-currency-label"><select id="near-currency" aria-label="Currency">${['THB','USD','EUR','JPY','GBP'].map(c=>`<option value="${c}" ${state.nearbyCurrency===c?'selected':''}>${c}</option>`).join('')}</select></label></div></div>${state.nearbyActive?`<p class="nearby-status">${html(state.nearbyList.length?`${state.nearbyList.length} ${state.lang==='th'?'สถานที่':'places'}`:t('noLocal'))}</p>`:''}`}
let nearbySeq=0;
async function fetchNearby(){
 if(!state.nearbyPoint||!LIVE_DATA)return;
 const current=++nearbySeq;state.nearbyBusy=true;render({keepScroll:true});
 const q=new URLSearchParams({lat:state.nearbyPoint.lat,lon:state.nearbyPoint.lon,radiusKm:state.nearbyRadius,category:state.category,currency:state.nearbyCurrency});
 if(state.nearbyMaxPrice!=='')q.set('maxPrice',state.nearbyMaxPrice);
 try{const result=await userApi('/api/places/nearby?'+q.toString());if(current!==nearbySeq)return;state.nearbyList=result.places;state.nearbyActive=true;state.region='all';state.mapSelected=result.places[0]?.id||'';
 if(state.page==='map')state.mapCenter={...state.nearbyPoint,z:state.nearbyRadius<=5?12:state.nearbyRadius<=25?10:8};
 }catch(e){if(current===nearbySeq)toast(e.message)}finally{if(current===nearbySeq){state.nearbyBusy=false;render({keepScroll:true})}}
}
function startNearby(){
 if(!LIVE_DATA){toast(t('localOnly'));return}
 if(!navigator.geolocation){toast(t('locationDenied'));return}
 state.nearbyBusy=true;render({keepScroll:true});
 navigator.geolocation.getCurrentPosition(position=>{
  state.nearbyPoint={lat:position.coords.latitude,lon:position.coords.longitude};fetchNearby();
 },()=>{state.nearbyBusy=false;toast(t('locationDenied'));render({keepScroll:true})},{enableHighAccuracy:false,timeout:12000,maximumAge:120000});
}
async function handleAccountLink(){
 const params=new URLSearchParams(location.search),verify=params.get('verify'),reset=params.get('reset');
 if(!verify&&!reset)return;
 // Clear one-time secrets from address and history immediately.
 history.replaceState(null,'',location.pathname+'#profile');state.page='profile';
 if(reset){state.resetToken=reset;state.authMode='reset';render();return}
 try{await userApi('/api/auth/verify','POST',{token:verify});await refreshSession();toast(t('emailVerified'))}
 catch(e){toast(e.message)}render({keepScroll:true});
}
function discover(){const found=filteredPlaces(),top=found.slice(0,state.showAll||state.category!=='all'||state.query||state.nearbyActive?found.length:4),extra=!state.nearbyActive&&state.category==='all'&&!state.query?PLACES.slice(4,8):[];return `<div class="app-shell explore-page">${header()}<main class="content-area"><div class="explore-heading"><div><p class="mini-overline">${html(t('exploreEyebrow'))}</p><h1>${html(t('exploreTitle')).replace('\n','<br>')}</h1></div><button data-action="search-open" class="vertical-search" aria-label="${html(t('searchShort'))}">${ico('search',25)}</button><p class="explore-quiet">${html(t('exploreIntro'))}</p></div>${categoryButtons()}${nearbyControls()}${!LIVE_DATA?`<div class="v21-demo-bar">${html(state.lang==='th'?'ข้อมูลตัวอย่าง · เผยแพร่สถานที่จริงจาก Admin Studio':'Preview listings · publish your own places from Admin Studio')} <a href="/admin.html">Admin ↗</a></div>`:''}<section class="spotlight-section"><div class="section-line"><h2>${state.nearbyActive?html(t('nearActive')):state.query?html(t('searchResults')):html(t('popular'))}</h2>${!state.nearbyActive&&!state.query&&state.category==='all'?`<button data-action="show-all" class="quiet-link">${html(t(state.showAll?'more':'showAll'))} ${ico('arrow',16)}</button>`:''}</div>${found.length?`<div class="featured-rail ${top.length<3?'few':''}">${top.map(x=>placeCard(x)).join('')}</div>`:`<div class="empty-light">${ico('search',27)}<h2>${html(t('nothing'))}</h2><p>${html(t('different'))}</p></div>`}</section>${extra.length&&!state.showAll?`<section class="secondary-section"><div class="section-line"><h2>${html(t('nearby'))}</h2><button data-action="show-all" class="quiet-link">${html(t('showAll'))} ${ico('arrow',16)}</button></div><div class="mini-grid">${extra.map(miniCard).join('')}</div></section>`:''}<div class="editorial-band"><div><span class="mini-overline">BEYOND THE MAP</span><h2>${state.lang==='th'?'การเดินทางที่ดี เริ่มจากความอยากรู้':'Good places.\nLess obvious paths.'.replace('\n','<br>')}</h2></div><button data-action="navigate" data-page="map" class="outline-light">${html(t('map'))} ${ico('arrow',19)}</button></div><footer class="micro-disclaimer">${html(LIVE_DATA?(state.lang==='th'?'ข้อมูลจัดทำโดยผู้ดูแล โปรดตรวจสอบก่อนเดินทาง':'Listings are supplied by the administrator; verify details before visiting'):t('photoNotice'))}</footer></main>${bottomNav()}</div>`}
function reviewSection(p){
 const own=state.myReviews.find(r=>r.placeId===p.id),approved=state.reviewCache[p.id]||[],total=approved.length;
 return `<details class="review-block"><summary><span>${ico('star',18)} ${html(t('publicReviews'))} <small>${total}</small></span>${ico('down',19)}</summary><div class="review-content">${approved.length?approved.map(r=>`<article class="review-card"><div class="review-title"><b>${html(r.name)}</b><span>${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</span></div><p>${html(r.text)}</p>${r.photo?`<img class="review-attachment" src="${html(r.photo)}" alt="Traveller review photo" loading="lazy"/>`:''}<small>${html(new Date(r.createdAt).toLocaleDateString(state.lang==='th'?'th-TH':'en-GB'))}</small></article>`).join(''):`<p class="profile-micro">${html(t('noReviews'))}</p>`}${state.account?`<form id="public-review-form" data-id="${html(p.id)}" class="public-review-form"><h3>${html(t('writeReview'))}</h3>${own?`<p class="review-state">${html(own.status==='approved'?t('reviewApproved'):own.status==='pending'?t('reviewPending'):t('reviewRejected'))}</p>`:''}<label>${html(t('rating'))}<select name="stars">${[5,4,3,2,1].map(n=>`<option value="${n}" ${own?.stars===n?'selected':''}>${n} ★</option>`).join('')}</select></label><label>${html(t('reviewBody'))}<textarea name="text" rows="3" minlength="10" maxlength="1500" required placeholder="${html(t('writeReview'))}">${html(own?.text||'')}</textarea></label><label class="review-photo-input">${ico('camera',17)} ${html(t('photoUpload'))}<input type="file" id="review-file" accept="image/png,image/jpeg,image/webp"/></label><div id="review-photo-preview">${state.reviewPhoto||own?.photo?`<img src="${html(state.reviewPhoto||own.photo)}" alt="Review photo preview"/>`:''}</div><div class="review-commands"><button class="action-lime" type="submit">${html(t('submitReview'))}</button>${own?`<button class="text-underlined" data-action="review-delete" data-id="${html(p.id)}" type="button">${html(t('removeReview'))}</button>`:''}</div><p class="profile-micro">${html(t('reviewCheck'))}</p></form>`:`<button class="review-signin" data-action="navigate" data-page="profile">${html(t('authNeeded'))} ${ico('arrow',15)}</button>`}</div></details>`
}
function detail(p){const saved=state.saved.includes(p.id),planned=state.trip.includes(p.id);return `<div class="detail-page">${header()}<main class="detail-grid"><div class="detail-photo"><img src="${photo(p.photo)}" alt="Destination cover image"/><div class="detail-gradient"></div><div class="detail-top-actions">${actionBtn('back',ico('left',23),'glass-icon','aria-label="Back"')}${heartButton(p,'detail-heart')}</div><div class="detail-photo-caption"><span>${ico('pin',16)} ${html(loc(p))}</span><h1>${html(name(p))}</h1><div class="image-counter"><i></i><i></i><i></i></div></div></div><div class="detail-info"><div class="detail-overline">${html(LIVE_DATA?(state.lang==='th'?'เผยแพร่แล้ว':'Published'):t('verified'))} · UNFOLD</div><div class="detail-title"><h2>${html(name(p))}</h2><small>${ico('pin',15)} ${html(loc(p))}</small></div><div class="detail-stats"><div>${ico('clock',21)}<span><strong>${html(p.visit)}</strong><small>${html(t('visit'))}</small></span></div><div>${ico(p.category==='food'?'coffee':p.category==='stay'?'bed':'tree',21)}<span><strong>${html(t(p.category))}</strong><small>${html(t('exploreType'))}</small></span></div><div>${ico('map',21)}<span><strong>${html(p.region==='north'?'North':p.region==='south'?'South':'Global')}</strong><small>${html(t('area'))}</small></span></div></div>${p.priceFrom!=null?`<p class="detail-price">${html(t('startingFrom'))} <strong>${html(new Intl.NumberFormat(state.lang==='th'?'th-TH':'en-US',{style:'currency',currency:p.currency||'THB',maximumFractionDigits:0}).format(p.priceFrom))}</strong></p>`:''}<section class="detail-about"><h3>${html(t('about'))}</h3><p>${html(story(p))}</p></section><section class="detail-gallery"><div class="detail-gallery-head"><h3>${html(t('gallery'))}</h3><span>01 — 03</span></div><div class="gallery-track">${p.gallery.map(img=>`<img src="${photo(img)}" alt="Destination photo" loading="lazy"/>`).join('')}</div></section><div class="detail-action-bar"><div><span class="action-kicker">${html(LIVE_DATA?(state.lang==='th'?'ตรวจสอบเวลาเปิดและความพร้อมก่อนเดินทาง':'Check access and opening conditions before visiting'):t('dataNotice'))}</span><button class="detail-save-inline" data-action="save" data-id="${p.id}">${ico('heart',17)} ${html(t(saved?'unsave':'save'))}</button></div><div class="detail-main-actions"><button class="action-outline" data-action="directions" data-id="${p.id}">${ico('route',17)} ${html(t('route'))}</button><button class="action-lime" data-action="trip-toggle" data-id="${p.id}">${html(t(planned?'removeTrip':'addTrip'))} ${ico(planned?'check':'arrow',19)}</button></div><div class="route-modes">${[['driving','modeDrive'],['walking','modeWalk'],['transit','modeTransit']].map(([id,key])=>`<button type="button" data-action="route-mode" data-mode="${id}" class="${state.travelMode===id?'on':''}">${html(t(key))}</button>`).join('')}</div></div>${LIVE_DATA?reviewSection(p):''}<details class="private-note"><summary>${ico('notebook',17)} ${html(t('review'))} ${ico('down',15)}</summary><form id="note-form" data-id="${p.id}"><textarea name="note" rows="3" maxlength="1000" placeholder="${html(t('notePlaceholder'))}">${html(state.notes[p.id]||'')}</textarea><button class="small-dark" type="submit">${html(t('saveNote'))}</button></form></details></div></main>${bottomNav()}</div>`}
const MAP_REGIONS={north:{lat:18.84,lon:98.98,z:9},south:{lat:8.2,lon:98.60,z:9},central:{lat:14.1,lon:100.6,z:9},northeast:{lat:16.3,lon:103.4,z:8},east:{lat:12.7,lon:101.3,z:9},west:{lat:14.2,lon:99.2,z:9},world:{lat:20,lon:10,z:3}};
function mapViewFor(list){
 const valid=list.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));
 if(!valid.length)return {...MAP_REGIONS.north};
 const lats=valid.map(p=>p.lat),lons=valid.map(p=>p.lon);
 const maxLat=Math.max(...lats),minLat=Math.min(...lats),maxLon=Math.max(...lons),minLon=Math.min(...lons);
 const lat=(maxLat+minLat)/2,lon=(maxLon+minLon)/2;
 let z=10;
 const dx=(maxLon-minLon)*Math.cos(lat*Math.PI/180),dy=maxLat-minLat;
 while(z>4&&Math.max(dx*256*(2**z)/360/0.8,dy*256*(2**z)/360/0.6)>510)z--;
 return {lat,lon,z};
}
function mapPage(){const places=(state.nearbyActive?filteredPlaces():PLACES.filter(p=>state.region==='all'||p.region===state.region)),pick=places.find(p=>p.id===state.mapSelected)||places[0];return `<div class="app-shell map-page">${header()}<main class="map-wrap"><div class="map-toolbar"><div><span class="mini-overline">UNFOLD / EXPLORE</span><h1>${html(t('map'))}</h1></div><label class="map-region-label">${html(t('mapArea'))}<select id="map-region"><option value="all" ${state.region==='all'?'selected':''}>${html(t('allRegions'))}</option>${Object.entries({north:"North Thailand",south:"South Thailand",central:"Central Thailand",northeast:"Northeast Thailand",east:"East Thailand",west:"West Thailand",world:"Other countries"}).map(([key,label])=>`<option value="${key}" ${state.region===key?'selected':''}>${html(label)}</option>`).join('')}</select></label></div>${nearbyControls()}<div class="map-layout"><div class="map-frame"><div class="map-paper"><div class="tile-layer" id="tile-layer"></div><div class="pin-layer" id="pin-layer"></div></div><div class="map-place-counter">${ico('pin',17)} ${places.length} ${html(state.lang==='th'?'สถานที่':'places')}</div><div class="map-controls"><button data-action="map-zoom" data-step="1" aria-label="${html(t('mapZoomIn'))}">${ico('plus',18)}</button><button data-action="map-zoom" data-step="-1" aria-label="${html(t('mapZoomOut'))}">${ico('minus',18)}</button></div><span class="map-copyright">© OpenStreetMap contributors</span></div><aside class="map-drawer"><div class="map-drawer-heading"><span>${html(t('list'))}</span><span>${places.length} places</span></div><div class="map-items">${places.map(p=>`<button class="map-result ${p.id===pick?.id?'active':''}" data-action="map-select" data-id="${p.id}"><img src="${photo(p.photo)}" alt=""/><span><b>${html(name(p))}</b><small>${html(loc(p))}</small></span>${ico('arrow',17)}</button>`).join('')}</div>${pick?`<div class="map-picked"><img src="${photo(pick.photo)}" alt=""/><div><strong>${html(name(pick))}</strong><small>${html(loc(pick))}</small></div><button data-action="place" data-id="${pick.id}">${ico('arrow',19)}</button></div>`:''}</aside></div><p class="map-disclaimer">${ico('info',13)} ${html(LIVE_DATA?(state.lang==='th'?'แผนที่จากพิกัดที่ผู้ดูแลเผยแพร่':'Map pins from published coordinates'):t('mapCaption'))}</p></main>${bottomNav()}</div>`}
function collection(){const trip=state.page==='trip',items=(trip?state.trip:state.saved).map(getPlace).filter(Boolean);return `<div class="app-shell collection-page ${trip?'trip-page':''}">${header()}<main class="collection-content"><div class="collection-intro"><span class="mini-overline">YOUR SPACE / UNFOLD</span><h1>${html(t('myCollections'))}<span class="tiny-accent">.</span></h1><p>${html(t('collections'))}</p></div><div class="collection-bar"><button data-action="navigate" data-page="saved" class="${!trip?'active':''}">${html(t('allSaved'))} <small>${state.saved.length}</small></button><button data-action="navigate" data-page="trip" class="${trip?'active':''}">${html(t('planTrip'))} <small>${state.trip.length}</small></button></div>${trip?`<div class="planner-quicklink"><a href="/planner.html">${state.lang==='th'?'จัดแผนเที่ยวตามวันและงบประมาณ':'Plan days & budget'} →</a></div>`:''}${items.length?`<div class="collection-grid">${items.map((p,i)=>`<div class="collection-item"><button class="collection-photo" data-action="place" data-id="${p.id}"><img src="${photo(p.photo)}" alt=""/><span><b>${html(name(p))}</b><small>${html(loc(p))}</small></span></button><div class="collection-actions">${trip?`<button data-action="move-trip" data-id="${p.id}" data-dir="-1" aria-label="Move up" ${i===0?'disabled':''}>${ico('up',16)}</button><button data-action="move-trip" data-id="${p.id}" data-dir="1" aria-label="Move down" ${i===items.length-1?'disabled':''}>${ico('down',16)}</button><button data-action="trip-toggle" data-id="${p.id}" aria-label="Remove from trip">${ico('trash',16)}</button>`:`<button data-action="save" data-id="${p.id}" aria-label="Remove from saved">${ico('heart',18)}</button><button data-action="trip-toggle" data-id="${p.id}">${ico(state.trip.includes(p.id)?'check':'plus',18)}</button>`}</div></div>`).join('')}</div>${trip?`<div class="trip-footer"><a class="action-lime" href="/planner.html" style="text-decoration:none">${state.lang==='th'?'วางแผนทริปหลายวัน':'Plan my days'} ${ico('arrow',17)}</a><button class="action-lime" data-action="trip-route">${html(t('planRoute'))} ${ico('arrow',17)}</button><button class="text-underlined" data-action="trip-clear">${html(t('clearTrip'))}</button></div>`:''}`:`<div class="collection-empty">${ico(trip?'map':'heart',34)}<h2>${html(t(trip?'emptyTrip':'emptySaved'))}</h2><button data-action="navigate" data-page="discover" class="action-lime">${html(t('homeExplore'))} ${ico('arrow',18)}</button></div>`}</main>${bottomNav()}</div>`}
function profile(){return `<div class="app-shell profile-page">${header()}<main class="profile-wrap"><div class="profile-header"><span class="mini-overline">UNFOLD / YOUR SPACE</span><h1>${html(t('profile'))}</h1><p>${html(t('profileSub'))}</p></div><div class="profile-sections"><section class="profile-card account-card"><h2>${html(t('accountTitle'))}</h2>${state.account?`<div class="account-ident"><span class="account-avatar">${html(state.account.name[0].toUpperCase())}</span><div><strong>${html(state.account.name)}</strong><small>${html(state.account.email)}</small></div></div><p class="profile-micro">${html(t('accountReady'))} · ${html(t(state.account.emailVerified?'emailVerified':'emailUnverified'))}</p>${!state.account.emailVerified?`<button class="account-link" type="button" data-action="auth-verify-request">${html(t('sendVerify'))}</button>`:''}<form id="member-name-form" class="member-name-form"><label>${html(t('changeName'))}<input name="name" value="${html(state.account.name)}" minlength="2" maxlength="60" required></label><button class="account-link" type="submit">${html(t('saveName'))} →</button></form><button class="account-signout" type="button" data-action="auth-logout">${html(t('signOut'))} ${ico('arrow',17)}</button>`:`<p class="profile-micro">${html(t('guestIntro'))}</p><div class="auth-tabs"><button data-action="auth-mode" data-mode="login" class="${state.authMode==='login'?'active':''}">${html(t('signIn'))}</button><button data-action="auth-mode" data-mode="register" class="${state.authMode==='register'?'active':''}">${html(t('signUp'))}</button></div>${state.authMode==='forgot'?`<form class="member-auth-form" id="member-forgot-form"><label>${html(t('email'))}<input name="email" type="email" required autocomplete="email" /></label><button class="action-lime" type="submit">${html(t('sendReset'))} →</button></form>`:state.authMode==='reset'?`<form class="member-auth-form" id="member-reset-form"><label>${html(t('resetPassword'))}<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required/></label><button class="action-lime" type="submit">${html(t('resetPassword'))} →</button></form>`:`<form class="member-auth-form" id="member-auth-form">${state.authMode==='register'?`<label>${html(t('displayName'))}<input name="name" type="text" autocomplete="name" minlength="2" maxlength="60" required/></label>`:''}<label>${html(t('email'))}<input name="email" type="email" autocomplete="email" maxlength="254" required/></label><label>${html(t('password'))}<input name="password" type="password" minlength="12" maxlength="128" autocomplete="${state.authMode==='register'?'new-password':'current-password'}" required/></label><button class="action-lime" type="submit" ${state.accountBusy?'disabled':''}>${html(t(state.authMode==='register'?'createAccount':'signIn'))} ${ico('arrow',17)}</button></form>`}<div class="auth-secondary"><button type="button" data-action="auth-mode" data-mode="${state.authMode==='login'?'forgot':'login'}">${html(t(state.authMode==='login'?'forgotPassword':'backToLogin'))}</button></div><p class="profile-micro">${html(t('guestSaved'))}</p>`}</section><section class="profile-card"><h2>${html(t('language'))}</h2><div class="language-switch"><button class="${state.lang==='en'?'active':''}" data-action="set-language" data-lang="en">English</button><button class="${state.lang==='th'?'active':''}" data-action="set-language" data-lang="th">ไทย</button></div></section><section class="profile-card"><h2>${html(t('suggestTitle'))}</h2><form id="suggest-form" class="suggest-form"><input name="name" maxlength="100" required placeholder="${html(t('name'))}" aria-label="${html(t('name'))}"/><input name="area" maxlength="120" required placeholder="${html(t('location'))}" aria-label="${html(t('location'))}"/><select name="category" aria-label="Category">${CATEGORIES.slice(1).map(c=>`<option value="${c}">${html(t(c))}</option>`).join('')}</select><textarea name="notes" maxlength="500" rows="2" placeholder="${html(t('notes'))}"></textarea><button class="action-lime" type="submit">${html(t('submit'))} ${ico('arrow',16)}</button></form><p class="profile-micro">${html(t('draftNotice'))}</p></section><section class="profile-card"><h2>${html(t('drafts'))} <span class="draft-count">${state.suggestions.length}</span></h2>${state.suggestions.length?state.suggestions.slice().reverse().slice(0,4).map(p=>`<div class="suggestion-row"><span><b>${html(p.name)}</b><small>${html(p.area)}</small></span>${ico('check',16)}</div>`).join(''):`<p class="profile-micro">—</p>`}<div class="profile-tools"><button data-action="export">${ico('upload',17)} ${html(t('export'))}</button><button data-action="reset">${ico('trash',17)} ${html(t('reset'))}</button><a class="studio-link" href="/business.html">For local businesses ↗</a><a class="studio-link" href="/admin.html">Admin Studio ↗</a></div></section></div><p class="bottom-info">${html(LIVE_DATA?(state.lang==='th'?'ตรวจสอบข้อมูลสถานที่ก่อนเดินทาง':'Verify access information before visiting'):t('dataNotice'))}</p></main>${bottomNav()}</div>`}
function overlayMenu(){return `<div class="mega-overlay" role="dialog" aria-modal="true" aria-label="Menu"><div class="overlay-top">${brand()}<button class="overlay-close" data-action="menu-close" aria-label="Close">${ico('x',26)}</button></div><div class="overlay-body"><div class="overlay-words">${[['discover','discover'],['map','map'],['saved','saved'],['trip','trip'],['profile','profile']].map(([page,label])=>`<button data-action="navigate" data-page="${page}" class="${state.page===page?'active':''}">${html(t(label))}${page==='saved'?`<sup>${state.saved.length}</sup>`:''}</button>`).join('')}</div><div class="overlay-polaroids">${PLACES.slice(0,3).map((p,i)=>`<button data-action="place" data-id="${p.id}" style="--tilt:${[-7,5,-4][i]}deg"><img src="${photo(p.photo)}" alt=""/><span>${html(name(p))}</span></button>`).join('')}</div></div><div class="overlay-foot">${html(t('menuSub'))}<span>© unfold · preview</span></div></div>`}
function searchOverlay(){return `<div class="search-overlay" role="dialog" aria-modal="true" aria-label="Search"><button class="search-backdrop" data-action="search-close" aria-label="Close search"></button><div class="search-panel"><div class="search-top">${ico('search',24)}<input id="overlay-search" type="search" autocomplete="off" aria-label="${html(t('search'))}" placeholder="${html(t('search'))}" value="${html(state.query)}"/><button data-action="search-close" aria-label="Close">${ico('x',20)}</button></div><div class="search-results">${filteredPlaces().slice(0,6).map(p=>`<button data-action="search-place" data-id="${p.id}"><img src="${photo(p.photo)}" alt=""/><span><strong>${html(name(p))}</strong><small>${html(loc(p))}</small></span>${ico('arrow',18)}</button>`).join('')||`<div class="search-empty">${html(t('nothing'))}</div>`}</div></div></div>`}
function appHtml(){let body=state.page==='welcome'?landing():state.page==='discover'?discover():state.page==='detail'?detail(getPlace(state.detail)||PLACES[0]):state.page==='map'?mapPage():state.page==='saved'||state.page==='trip'?collection():profile();return body+(state.menuOpen?overlayMenu():'')+(state.searchOpen?searchOverlay():'')}
let restoringScroll=false;
function render({keepScroll=false}={}){const sy=keepScroll?window.scrollY:0;document.documentElement.lang=state.lang;document.title=`unfold — ${state.page==='welcome'?'discover differently':t(state.page==='detail'?'titlePlace':state.page)}`;$('#app').innerHTML=appHtml();document.body.classList.toggle('has-modal',state.menuOpen||state.searchOpen);if(state.page==='map')requestAnimationFrame(drawMap);if(keepScroll)requestAnimationFrame(()=>window.scrollTo({top:sy,behavior:'instant'}));else window.scrollTo({top:0,behavior:'instant'})}
function navigate(page,updateHash=true){state.page=page;state.menuOpen=false;state.searchOpen=false;state.showAll=false;state.query='';if(page!=='detail')state.detail=null;if(page==='map'){const reg=state.region==='all'?'north':state.region;state.mapCenter=state.nearbyActive&&state.nearbyPoint?{...state.nearbyPoint,z:state.nearbyRadius<=5?12:state.nearbyRadius<=25?10:8}:{...MAP_REGIONS[reg],...(state.region==='all'&&LIVE_DATA?mapViewFor(PLACES):{})}};if(updateHash)history.replaceState(null,'',page==='welcome'?location.pathname:('#'+page));render()}
function place(id){if(!getPlace(id))return;state.previous=state.page==='detail'?state.previous:state.page;state.detail=id;state.page='detail';state.menuOpen=false;state.searchOpen=false;history.replaceState(null,'','#place='+id);state.reviewPhoto='';render();loadReviewPage(id)}
function savePlace(id){if(state.account&&!LIVE_DATA){toast(state.lang==='th'?'สถานที่ตัวอย่างยังซิงก์ไม่ได้':'Preview places cannot be saved to your account');return}state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persistCollections();render({keepScroll:true});toast(t(state.saved.includes(id)?'done':'removed'))}
function toggleTrip(id){if(state.account&&!LIVE_DATA){toast(state.lang==='th'?'สถานที่ตัวอย่างยังซิงก์ไม่ได้':'Preview places cannot be saved to your account');return}state.trip=state.trip.includes(id)?state.trip.filter(x=>x!==id):[...state.trip,id];persistCollections();render({keepScroll:true});toast(t(state.trip.includes(id)?'done':'removedTrip'))}
function externalDirections(id){const p=getPlace(id);if(!p)return;if(p.concept){toast(state.lang==='th'?'หมวดตัวอย่างยังไม่มีจุดหมายที่ยืนยัน':'This preview collection has no verified destination');return}const destination=encodeURIComponent(LIVE_DATA&&Number.isFinite(p.lat)&&Number.isFinite(p.lon)?`${p.lat},${p.lon}`:p.en+', '+p.locEn);window.open('https://www.google.com/maps/dir/?api=1&destination='+destination+'&travelmode='+state.travelMode,'_blank','noopener,noreferrer')}
function externalTrip(){if(!state.trip.length)return;const p=state.trip.map(getPlace).filter(Boolean),fmt=x=>encodeURIComponent(LIVE_DATA&&Number.isFinite(x.lat)&&Number.isFinite(x.lon)?`${x.lat},${x.lon}`:x.en+', '+x.locEn);let url='https://www.google.com/maps/dir/?api=1&destination='+fmt(p[p.length-1]);if(p.length>1){url+='&origin='+fmt(p[0]);if(p.length>2)url+='&waypoints='+encodeURIComponent(p.slice(1,-1).slice(0,9).map(x=>LIVE_DATA&&Number.isFinite(x.lat)&&Number.isFinite(x.lon)?`${x.lat},${x.lon}`:x.en+', '+x.locEn).join('|'))}window.open(url,'_blank','noopener,noreferrer')}
function exportData(){const data=JSON.stringify({app:'unfold',version:2,exported:new Date().toISOString(),saved:state.saved,trip:state.trip,notes:state.notes,suggestions:state.suggestions},null,2);const href=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download='unfold-my-data.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),5000)}
function dispatch(event){const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;event.preventDefault();switch(action){
 case'navigate':navigate(target.dataset.page);break;
 case'place':case'search-place':place(id);break;
 case'back':if(state.previous==='welcome')navigate('discover');else navigate(state.previous||'discover');break;
 case'language':state.lang=state.lang==='en'?'th':'en';store();render({keepScroll:true});break;
 case'set-language':state.lang=target.dataset.lang;store();render({keepScroll:true});break;
 case'category':state.category=target.dataset.category;state.showAll=false;if(state.nearbyActive)fetchNearby();else render({keepScroll:true});break;
 case'nearby-start':startNearby();break;
 case'filter-toggle':state.filtersOpen=!state.filtersOpen;render({keepScroll:true});break;
 case'nearby-stop':nearbySeq++;state.nearbyBusy=false;state.nearbyActive=false;state.nearbyList=[];state.nearbyPoint=null;state.region='all';render({keepScroll:true});break;
 case'route-mode':state.travelMode=target.dataset.mode;render({keepScroll:true});break;
 case'auth-verify-request':userApi('/api/auth/verify/request','POST',{}).then(()=>toast(t('emailCheck'))).catch(e=>toast(e.message));break;
 case'show-all':state.showAll=!state.showAll;render({keepScroll:true});break;
 case'save':savePlace(id);break;
 case'trip-toggle':toggleTrip(id);break;
 case'directions':externalDirections(id);break;
 case'trip-route':externalTrip();break;
 case'trip-clear':if(confirm(state.lang==='th'?'ล้างทริปทั้งหมดหรือไม่?':'Clear every trip stop?')){state.trip=[];persistCollections();render()}break;
 case'move-trip':{const i=state.trip.indexOf(id),j=i+Number(target.dataset.dir);if(j>=0&&j<state.trip.length){[state.trip[i],state.trip[j]]=[state.trip[j],state.trip[i]];persistCollections();render({keepScroll:true})}break;}
 case'menu-open':state.menuOpen=true;render({keepScroll:true});break;
 case'menu-close':state.menuOpen=false;render({keepScroll:true});break;
 case'search-open':state.searchOpen=true;render({keepScroll:true});$('#overlay-search')?.focus();break;
 case'search-close':state.searchOpen=false;state.query='';render({keepScroll:true});break;
 case'map-select':if(window.innerWidth<=700)place(id);else{state.mapSelected=id;render({keepScroll:true})}break;
 case'map-zoom':state.mapCenter.z=Math.max(3,Math.min(14,state.mapCenter.z+Number(target.dataset.step)));drawMap();break;
 case'auth-mode':state.authMode=['login','register','forgot'].includes(target.dataset.mode)?target.dataset.mode:'login';render({keepScroll:true});break;
 case'auth-logout':signOut();break;
 case'review-delete':if(confirm(state.lang==='th'?'ลบรีวิวของคุณหรือไม่?':'Delete your review?')){userApi('/api/places/'+encodeURIComponent(id)+'/my-review','DELETE').then(()=>{state.myReviews=state.myReviews.filter(r=>r.placeId!==id);state.reviewPhoto='';loadReviewPage(id);render({keepScroll:true})}).catch(e=>toast(e.message))}break;
 case'export':exportData();toast(t('done'));break;
 case'reset':if(confirm(state.lang==='th'?'ลบข้อมูลที่บันทึกในเครื่องทั้งหมดหรือไม่?':'Reset all local saved data?')){state.saved=[];state.trip=[];state.notes={};state.suggestions=[];store();render();}break;
 default:break;
 }}
function onSubmit(event){
 if(event.target.id==='member-forgot-form'){
  event.preventDefault();const f=new FormData(event.target);
  userApi('/api/auth/password/forgot','POST',{email:String(f.get('email')||'')}).then(()=>toast(t('emailCheck'))).catch(e=>toast(e.message));return;
 }
 if(event.target.id==='member-reset-form'){
  event.preventDefault();const f=new FormData(event.target);
  userApi('/api/auth/password/reset','POST',{token:state.resetToken,password:String(f.get('password')||'')}).then(()=>{state.resetToken='';state.authMode='login';render({keepScroll:true});toast(t('resetReady'))}).catch(e=>toast(e.message));return;
 }
 if(event.target.id==='member-name-form'){
  event.preventDefault();const f=new FormData(event.target);
  userApi('/api/me/profile','PATCH',{name:String(f.get('name')||'')}).then(r=>{state.account=r.user;render({keepScroll:true});toast(t('profileUpdated'))}).catch(e=>toast(e.message));return;
 }
 if(event.target.id==='member-auth-form'){
  event.preventDefault();if(state.accountBusy)return;const f=new FormData(event.target);state.accountBusy=true;
  const mode=state.authMode==='register'?'register':'login';
  userApi('/api/auth/'+mode,'POST',{name:String(f.get('name')||''),email:String(f.get('email')||''),password:String(f.get('password')||'')}).then(async data=>{
   state.account=data.user;state.accountBusy=false;state.reviewPhoto='';await loadAccountCollections();toast(data.verificationRequired?t('emailCheck'):t('accountSuccess'));
  }).catch(e=>{state.accountBusy=false;toast(e.message);render({keepScroll:true})});
  return;
 }
 if(event.target.id==='public-review-form'){
  event.preventDefault();if(!state.account)return;const id=event.target.dataset.id,f=new FormData(event.target),old=state.myReviews.find(r=>r.placeId===id);
  userApi('/api/places/'+encodeURIComponent(id)+'/my-review','PUT',{stars:Number(f.get('stars')),text:String(f.get('text')||''),photo:state.reviewPhoto||old?.photo||''}).then(async data=>{
   state.myReviews=state.myReviews.filter(r=>r.placeId!==id).concat(data.review);state.reviewPhoto='';await loadReviewPage(id);toast(t('reviewPending'));render({keepScroll:true});
  }).catch(e=>toast(e.message));return;
 }
 if(event.target.id==='note-form'){event.preventDefault();const id=event.target.dataset.id,form=new FormData(event.target);state.notes[id]=String(form.get('note')||'').trim().slice(0,1000);store();toast(t('done'));return}
 if(event.target.id==='suggest-form'){event.preventDefault();const form=new FormData(event.target);state.suggestions.push({name:String(form.get('name')||'').trim().slice(0,100),area:String(form.get('area')||'').trim().slice(0,120),category:String(form.get('category')||'nature'),notes:String(form.get('notes')||'').trim().slice(0,500),created:new Date().toISOString()});store();render({keepScroll:true});toast(t('done'))}}
function onInput(event){if(event.target.id==='overlay-search'){const input=event.target;const start=input.selectionStart;state.query=input.value;const results=$('.search-results');if(results)results.innerHTML=filteredPlaces().slice(0,6).map(p=>`<button data-action="search-place" data-id="${p.id}"><img src="${photo(p.photo)}" alt=""/><span><strong>${html(name(p))}</strong><small>${html(loc(p))}</small></span>${ico('arrow',18)}</button>`).join('')||`<div class="search-empty">${html(t('nothing'))}</div>`;return}}
function onChange(event){
 if(['near-radius','near-price','near-currency'].includes(event.target.id)){
  state.nearbyRadius=Number($('#near-radius')?.value||state.nearbyRadius);
  state.nearbyMaxPrice=$('#near-price')?.value??state.nearbyMaxPrice;
  state.nearbyCurrency=$('#near-currency')?.value||state.nearbyCurrency;
  if(state.nearbyActive)fetchNearby();else render({keepScroll:true});return;
 }
 if(event.target.id==='review-file'){
   const file=event.target.files?.[0];if(!file)return;
   if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('PNG / JPG / WebP · max 5 MB');return}
   const reader=new FileReader();reader.onload=()=>{
    userApi('/api/reviews/upload','POST',{dataUrl:reader.result}).then(r=>{
      state.reviewPhoto=r.url;const preview=$('#review-photo-preview');if(preview)preview.innerHTML=`<img src="${html(r.url)}" alt="Review photo preview"/>`;
    }).catch(e=>toast(e.message))
   };reader.readAsDataURL(file);return;
 }
 if(event.target.id==='map-region'){nearbySeq++;state.nearbyActive=false;state.nearbyPoint=null;state.nearbyList=[];state.region=event.target.value;const reg=state.region==='all'?'north':state.region;state.mapCenter=state.region==='all'&&LIVE_DATA?mapViewFor(PLACES):{...MAP_REGIONS[reg]};const first=PLACES.find(p=>state.region==='all'||p.region===reg);state.mapSelected=first?.id||PLACES[0]?.id||'';render({keepScroll:true})}}
const merc=(lat,lon,z)=>{const scale=256*(2**z),s=Math.sin(Math.max(-85,Math.min(85,lat))*Math.PI/180);return{x:(lon+180)/360*scale,y:(.5-Math.log((1+s)/(1-s))/(4*Math.PI))*scale}};
function drawMap(){if(state.page!=='map')return;const box=$('.map-paper'),tileLayer=$('#tile-layer'),pinLayer=$('#pin-layer');if(!box||!tileLayer||!pinLayer)return;const w=box.offsetWidth,h=box.offsetHeight;if(!w||!h)return;const {lat,lon,z}=state.mapCenter,origin=merc(lat,lon,z),tx=Math.floor((origin.x-w/2)/256),ty=Math.floor((origin.y-h/2)/256),max=2**z;tileLayer.innerHTML='';const fragment=document.createDocumentFragment();let count=0;for(let x=tx;x<=Math.ceil((origin.x+w/2)/256);x++){for(let y=ty;y<=Math.ceil((origin.y+h/2)/256);y++){if(y<0||y>=max||count++>42)continue;const tile=document.createElement('img');tile.alt='';tile.draggable=false;tile.loading='lazy';tile.style.left=(x*256-origin.x+w/2)+'px';tile.style.top=(y*256-origin.y+h/2)+'px';tile.onerror=()=>{tile.remove()};tile.src=`https://tile.openstreetmap.org/${z}/${((x%max)+max)%max}/${y}.png`;fragment.append(tile)}}tileLayer.append(fragment);
 const region=state.region==='all'?'north':state.region;pinLayer.innerHTML=(state.nearbyActive?filteredPlaces():PLACES.filter(p=>state.region==='all'||p.region===region)).map(p=>{const xy=merc(p.lat,p.lon,z),px=xy.x-origin.x+w/2,py=xy.y-origin.y+h/2;if(px<0||px>w||py<0||py>h)return '';return `<button class="map-pin ${state.mapSelected===p.id?'active':''}" style="left:${px}px;top:${py}px" data-action="map-select" data-id="${p.id}" aria-label="${html(name(p))}">${ico(p.category==='food'?'coffee':p.category==='stay'?'bed':'pin',19)}</button>`}).join('')+(state.nearbyActive&&state.nearbyPoint?`<div class="map-me-pin" style="left:${merc(state.nearbyPoint.lat,state.nearbyPoint.lon,z).x-origin.x+w/2}px;top:${merc(state.nearbyPoint.lat,state.nearbyPoint.lon,z).y-origin.y+h/2}px" title="Your location"><span></span></div>`:'')}
function initFromUrl(){const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('place=')){const id=hash.slice(6);state.page='detail';state.detail=id;state.previous='discover';return}if(['welcome','discover','map','saved','trip','profile'].includes(hash)){state.page=hash;if(hash==='map')state.mapCenter={...MAP_REGIONS.north}}}
const app=$('#app');document.addEventListener('click',dispatch);document.addEventListener('submit',onSubmit);document.addEventListener('input',onInput);document.addEventListener('change',onChange);document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.menuOpen){state.menuOpen=false;render({keepScroll:true})}else if(state.searchOpen){state.searchOpen=false;render({keepScroll:true})}else if(state.page==='detail')navigate(state.previous||'discover')}});
window.addEventListener('hashchange',()=>{if(!location.hash){navigate('welcome',false)}else if(location.hash.slice(1).startsWith('place=')){place(location.hash.slice(7))}else{const page=location.hash.slice(1);if(['welcome','discover','map','saved','trip','profile'].includes(page)&&page!==state.page)navigate(page,false)}});
window.addEventListener('resize',()=>{if(state.page==='map')drawMap()});
initFromUrl();render();handleAccountLink();
// Fetch live, published content. The older built-in places stay clearly marked as previews
// only until the Admin Studio has published at least one real record.
let placeLoadSeq=0;
async function refreshPublishedPlaces(){
 const seq=++placeLoadSeq;
 try{
  const res=await fetch('/api/places',{cache:'no-store'});
  if(!res.ok)throw new Error('Places service unavailable');
  const result=await res.json();
  if(!Array.isArray(result.places))throw new Error('Invalid place response');
  if(seq!==placeLoadSeq)return;
  API_ONLINE=true;LIVE_DATA=result.places.length>0;
  PLACES=LIVE_DATA?result.places:[...SAMPLE_PLACES];
  state.saved=state.saved.filter(id=>getPlace(id));state.trip=state.trip.filter(id=>getPlace(id));
  if(!getPlace(state.mapSelected))state.mapSelected=PLACES[0]?.id||'';
  if(LIVE_DATA&&state.region==='all')state.mapCenter=mapViewFor(PLACES);
  if(state.page==='detail'&&!getPlace(state.detail)){navigate('discover',true);return;}
  render({keepScroll:true});if(state.nearbyActive&&state.nearbyPoint)fetchNearby();if(state.page==='detail')loadReviewPage(state.detail);
 }catch(error){console.info('Showing unfold preview places (backend unavailable):',error.message)}
}
refreshPublishedPlaces().then(refreshSession);
window.addEventListener('focus',()=>{if(location.protocol.startsWith('http'))refreshPublishedPlaces()});
if('serviceWorker' in navigator && location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
